import{_ as t,o,c as d,a2 as e}from"./chunks/framework.1lR7qgqY.js";const b=JSON.parse('{"title":"一頁決策摘要","description":"","frontmatter":{},"headers":[],"relativePath":"decide/summary.md","filePath":"decide/summary.md","lastUpdated":1793014002000}'),r={name:"decide/summary.md"};function i(l,a,s,c,h,n){return o(),d("div",null,[...a[0]||(a[0]=[e('<h1 id="一頁決策摘要" tabindex="-1">一頁決策摘要 <a class="header-anchor" href="#一頁決策摘要" aria-label="Permalink to &quot;一頁決策摘要&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本頁屬性</p><ul><li>等級: 決策參考</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-26</li></ul></div><p><strong>結論</strong>: 自架 AI 在「資料不適合送到外部雲端, 使用量穩定, 且有人固定維運」三項同時成立時才有明顯優勢; 只符合其中一項時, 雲端 API 或混合做法通常較省事 (信心: 中, 屬推論).</p><h2 id="三項判斷前提" tabindex="-1">三項判斷前提 <a class="header-anchor" href="#三項判斷前提" aria-label="Permalink to &quot;三項判斷前提&quot;">​</a></h2><table tabindex="0"><thead><tr><th>前提</th><th>自架較合理的情況</th><th>雲端較合理的情況</th></tr></thead><tbody><tr><td>資料</td><td>內部規範或合約要求資料留在自己的環境內</td><td>資料可交給具備相應保證的雲端服務</td></tr><tr><td>使用量</td><td>長期穩定且用量高, 能攤提硬體</td><td>用量小或波動大, 按量計費較划算</td></tr><tr><td>維運</td><td>有人每週檢查安全公告, 備份與升級</td><td>沒有固定維運人員</td></tr></tbody></table><p>模型能力是第四項前提: 開放權重模型的能力與雲端旗艦模型之間有差距, 差距是否影響自己的任務, 請用自己的題目實測 (見 <a href="/docs-handbook-poc/build/m6-observability">M6</a>).</p><h2 id="自架要付出什麼" tabindex="-1">自架要付出什麼 <a class="header-anchor" href="#自架要付出什麼" aria-label="Permalink to &quot;自架要付出什麼&quot;">​</a></h2><ul><li><strong>硬體</strong>: 顯示記憶體或統一記憶體的容量, 常比運算速度更常決定能跑哪些模型 (見 <a href="/docs-handbook-poc/know/k2-quantization">K2</a>).</li><li><strong>人力</strong>: 備份, 版本鎖定, 安全公告, 金鑰輪替是持續工作, 不是安裝一次就結束的工作 (見 <a href="/docs-handbook-poc/ops/backup">O1 至 O3</a>).</li><li><strong>風險</strong>: 2026 年已知的事件多出在推論引擎之上的中介層, 例如閘道與低程式碼平台, 而非模型本身 (見<a href="/docs-handbook-poc/start/map">「架構地圖」</a>, 細節見 M5, K6, M7).</li></ul><h2 id="建議的下一步" tabindex="-1">建議的下一步 <a class="header-anchor" href="#建議的下一步" aria-label="Permalink to &quot;建議的下一步&quot;">​</a></h2><ol><li>用<a href="/docs-handbook-poc/decide/should-self-host">決策樹</a>得到初步方向.</li><li>用<a href="/docs-handbook-poc/decide/tco">成本試算表</a>填入自己的數字.</li><li>用<a href="/docs-handbook-poc/decide/risk-checklist">風險自評</a>確認維運前提.</li><li>方向仍是自架時, 用 <a href="/docs-handbook-poc/decide/poc-30days">30 天 PoC</a> 以最小代價驗證, 再決定是否投資硬體.</li></ol><p>本手冊不含法規解讀. 涉及資料保護, 契約或產業規範的判斷, 請洽法律顧問.</p>',11)])])}const u=t(r,[["render",i]]);export{b as __pageData,u as default};
